def ph_from_h_concentration(h_conc):
    LN10 = math.log(10.0)
    return -math.log(h_conc) / LN10






def shelf_life_q10(base_life, q10, temp_increase):
    exponent = temp_increase / 10.0

    return base_life / math.exp(exponent * math.log(q10))






def thermal_death_time(d_value, log_reduction):
    return d_value * log_reduction






def d_value_from_z(d_ref, z_value, temp, ref_temp):
    LN10 = math.log(10.0)
    exponent = (ref_temp - temp) / z_value
    return d_ref * math.exp(exponent * LN10)






def pasteurization_units(time_min, temp, z_value, ref_temp):
    LN10 = math.log(10.0)
    exponent = (temp - ref_temp) / z_value
    return time_min * math.exp(exponent * LN10)






